from collections import deque

def dfs_in_order(node):
    if not node:
        return
    dfs_in_order(node.left)
    print(node.value)
    dfs_in_order(node.right)

def bfs(root):
    if not root:
        return
    queue = deque([root])
    while queue:
        current = queue.popleft()
        print(current.value)
        if current.left:
            queue.append(current.left)
        if current.right:
            queue.append(current.right)

dfs_in_order(bst.root)
